import {
	normalizeGlyphMap,
	type NanoGlyphMap,
	type NanoGlyphMapInput,
	type GlyphEntry,
} from './glyphmap'

import type { NanoFontSource, NanoFontStatus, NanoIconSetProps } from './props'

/**
 * A registered icon font set. `Icon` is the bound component; `ready` resolves
 * once the platform font registration completes (or reports the reason it
 * could not — icons render fallback glyphs until then).
 */
export interface NanoIconSet<Name extends string = string> {
	/** Runtime font family — `<fontFamily>-<hash8>` as generated by the build. */
	readonly family: string
	/** Configured set name (`family` without the hash suffix). */
	readonly name: string
	readonly glyphMap: NanoGlyphMap
	readonly iconNames: readonly Name[]
	readonly ready: Promise<NanoFontStatus>
	readonly Icon: (props: NanoIconSetProps<Name>) => any
}

/** Registry of created sets — drives unbound `NanoIcon` name resolution. */
// Sets are stored erased — the name literal is compile-time only.
const sets = new Map<string, NanoIconSet<any>>()
const familySets = new Map<string, NanoIconSet<any>>()
const listeners = new Set<() => void>()
let revision = 0

// Components subscribe through ui's useStore so registering a set after mount
// updates unbound `NanoIcon`s, matching the previous collection behavior.
export const nanoIconSetRegistry = {
	getSnapshot: (): number => revision,
	subscribe(notify: () => void) {
		listeners.add(notify)
		return (): void => {
			listeners.delete(notify)
		}
	},
}

const HASH_SUFFIX = /-[0-9a-f]{8}$/

export function configuredFontFamily(family: string): string {
	return family.replace(HASH_SUFFIX, '')
}

export function registerNanoIconSet<Name extends string>(
	set: NanoIconSet<Name>,
): NanoIconSet<Name> {
	sets.set(set.name, set)
	familySets.set(set.family, set)
	revision++
	// oxlint-disable-next-line unicorn/no-useless-spread
	for (const notify of [...listeners]) {
		notify()
	}

	return set
}

/** Resolve `name` against `set`, or across every registered set. */
export function resolveNanoIcon(
	name: string,
	set?: NanoIconSet,
): { set: NanoIconSet<any>; entry: GlyphEntry } | undefined {
	if (set) {
		const entry = set.glyphMap.i[name]
		return entry ? { set, entry } : undefined
	}

	// Full-name match wins: iconify-style names already carry `prefix:`.
	const matches: { set: NanoIconSet; entry: GlyphEntry }[] = []
	for (const candidate of sets.values()) {
		const entry = candidate.glyphMap.i[name]
		if (entry) {
			matches.push({ set: candidate, entry })
		}
	}

	if (matches.length === 1) {
		return matches[0]
	}

	if (matches.length > 1) {
		console.warn(
			`[nano-icons] Icon name "${name}" exists in ${matches.length} sets; qualify it as "family:${name}" or pass a \`set\` prop`,
		)

		return matches[0]
	}

	// `family:icon` — try the registered set name or runtime family.
	const split = name.indexOf(':')
	if (split > 0) {
		const qualifier = name.slice(0, split)
		const iconName = name.slice(split + 1)
		const qualified = sets.get(qualifier) ?? familySets.get(qualifier)
		if (qualified) {
			const entry = qualified.glyphMap.i[iconName] ?? qualified.glyphMap.i[name]
			if (entry) {
				return { set: qualified, entry }
			}
		}
	}

	return undefined
}

/**
 * Platform halves of `createNanoIconSet` — each platform module supplies the
 * font registration call and the bound component factory.
 */
export interface CreateNanoIconSetHooks {
	registerFont: (family: string, source: NanoFontSource | undefined) => Promise<NanoFontStatus>
	/** The platform's compiled `NanoIcon` component (universal lanes need a compiler-defined component). */
	icon: (props: NanoIconSetProps<any>) => any
}

export function createNanoIconSetImpl<Name extends string>(
	glyphMapInput: NanoGlyphMapInput,
	options: { font?: NanoFontSource; name?: string } | undefined,
	hooks: CreateNanoIconSetHooks,
): NanoIconSet<Name> {
	const glyphMap = normalizeGlyphMap(glyphMapInput)
	const family = glyphMap.m.f
	const set = {
		family,
		name: options?.name ?? configuredFontFamily(family),
		glyphMap,
		iconNames: Object.keys(glyphMap.i) as Name[],
		ready: hooks.registerFont(family, options?.font),
		Icon: hooks.icon as NanoIconSet<Name>['Icon'],
	}

	return registerNanoIconSet(set as NanoIconSet<Name>) as NanoIconSet<Name>
}
